// Reproduces: Markdown bullets generated by a redline reuse numbering IDs that
// already exist in the source numbering.xml, so after merge (or Word's
// insertOoxml) the new "bullets" resolve to the document's existing decimal list.
// Exits 0 while the defect reproduces against the installed package.
//
//   node docs/library-issues/completed/2026-10-01-generated-bullet-numbering-collision-reproducer.mjs
import '../../../tests/setup-xml-provider.mjs';
import { inspectDocumentParts } from '@ansonlai/docx-redline-js';
import { applyOperationsToDocumentXml } from '@ansonlai/docx-redline-js/standalone-runner';

const W = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"';
const numberingXml = `<w:numbering ${W}>`
  + '<w:abstractNum w:abstractNumId="0"><w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/></w:lvl></w:abstractNum>'
  + '<w:num w:numId="1"><w:abstractNumId w:val="0"/></w:num></w:numbering>';
const documentXml = `<w:document ${W}><w:body>`
  + '<w:p><w:pPr><w:numPr><w:ilvl w:val="0"/><w:numId w:val="1"/></w:numPr></w:pPr><w:r><w:t>Existing numbered item.</w:t></w:r></w:p>'
  + '<w:p><w:r><w:t>Plain provision.</w:t></w:r></w:p>'
  + '<w:sectPr/></w:body></w:document>';
const target = inspectDocumentParts({ documentXml, numberingXml }).paragraphs[1];

const result = await applyOperationsToDocumentXml(documentXml, [{
  type: 'redline',
  target: { index: 2, exactText: target.exactText, paragraphId: target.paragraphId, fingerprint: target.fingerprint },
  modified: 'Rewritten provision:\n- First bullet.\n- Second bullet.',
  structuredContent: true
}], 'Reproducer', { numberingXml }, { atomic: true, generateRedlines: true, structuredContent: true });

const bulletNumIds = [...result.documentXml.matchAll(/<w:p\b(?:(?!<\/w:p>)[\s\S])*?<w:numId w:val="(\d+)"\/>(?:(?!<\/w:p>)[\s\S])*?(First|Second) bullet/g)]
  .map(match => match[1]);
const existing = new Set([...numberingXml.matchAll(/<w:num w:numId="(\d+)"/g)].map(match => match[1]));
const collides = bulletNumIds.length === 2 && bulletNumIds.every(id => existing.has(id));
console.log(`status=${result.status}; generated bullet numIds=${JSON.stringify(bulletNumIds)}; existing source numIds=${JSON.stringify([...existing])}`);
console.log(collides
  ? 'REPRODUCED: generated bullets reuse an existing (decimal) numbering instance ID.'
  : 'NOT REPRODUCED: generated bullets use a fresh numbering instance.');
process.exit(collides ? 0 : 1);
